        x.wrapping_sub(y as u8) as i8
    }
}

impl WrappingSub for i16 {
    fn wrapping_sub(self: i16, y: i16) -> i16 {
        let x = self as u16;
        x.wrapping_sub(y as u16) as i16
    }
