use crate::utils::{constants::{SCALE, SORTINO_DOWNSIDE_MINIMUM}, sqrt::sqrt};

pub fn sortino(
    actual_len: u32,
    bypass_confidence: bool,
    downside_variance_val: i64,
    ann_excess_return_val: i64,
    noconfidence_value: i64,
