}

#[test]
fn test_average_zeros() {
    let mut returns = [0; ARRAY_SIZE];
    for i in 0..10 {
        returns[i] = 0;
    }

    let weights = [100000; ARRAY_SIZE];
    let result = average(returns, 10, weights, false, 10);
